using UnityEngine;

// The game's sound effects, looked up by name: Sfx.Play("shoot").
// Tune volumes here (Assets/Resources/SoundLibrary). The WAV files
// are generated by Tools/generate_sfx.py.
[CreateAssetMenu(fileName = "SoundLibrary", menuName = "Contra/Sound Library")]
public class SoundLibrary : ScriptableObject
{
    [System.Serializable]
    public class Sound
    {
        public string name;
        public AudioClip clip;

        [Range(0f, 1f)]
        public float volume = 0.5f;

        // Random pitch change each time it plays (0.05 = +/- 5%)
        [Range(0f, 0.5f)]
        public float pitchVariation = 0f;

        // Ignore repeats closer together than this (seconds),
        // so ten explosions in one frame don't play ten times
        public float minInterval = 0.03f;
    }

    [Range(0f, 1f)]
    public float masterVolume = 0.8f;

    public Sound[] sounds;
}
